using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {typeInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Type the default resolver *can* resolve (any public type works with reflection)
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? personInfo))
    Console.WriteLine($"TryGet succeeded for {personInfo!.Type.Name}");
else
    Console.WriteLine("TryGet failed for Person");

// 2b. Build options with NO resolver → TryGet returns false instead of throwing
var empty = new JsonSerializerOptions { TypeInfoResolver = null };
if (empty.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGet succeeded (unexpected)");
else
    Console.WriteLine("TryGet correctly returned false — no resolver configured");

public record Person(string Name, int Age);

